// Package ruyisite carries files that are compiled into the binary.
package ruyisite

import (
	"embed"
	"io/fs"
)

// StaticAllowlist is server/static-allowlist.txt (generated by `make allowlist`).
//
//go:embed static-allowlist.txt
var StaticAllowlist string

//go:embed web
var webFS embed.FS

//go:embed vendor/katex
var katexFS embed.FS

// Pages is the embedded page tree (server/web): m/practice/index.html.
func Pages() fs.FS { return sub(webFS, "web") }

// KaTeX is the embedded KaTeX tree (server/vendor/katex), rooted at katex.min.js.
func KaTeX() fs.FS { return sub(katexFS, "vendor/katex") }

func sub(f embed.FS, dir string) fs.FS {
	s, err := fs.Sub(f, dir)
	if err != nil { // only possible for a malformed dir name: a programming error
		panic(err)
	}
	return s
}
